contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}();

        uint256 beforeBal = c.balances(address(this));

        bool reverted;
        if (withdrawAmount > beforeBal) {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }

            assert(reverted);
            assert(c.balances(address(this)) == beforeBal);
        } else {
            c.withdraw(withdrawAmount);

            assert(c.balances(address(this)) == beforeBal - withdrawAmount);
        }
    }

    receive() external payable {}
}

